const Component = () => {
  const [maxWidth, setMaxWidth] = useState(150);
  const ref = useCanvas((ctx, { color }) => {
    const text = "Hello World!";
    ctx.font = `600 40px ${color("font")}`;
    ctx.fillStyle = color("accent");
    ctx.fillText(text, 40, 56);
    ctx.fillText(text, 40, 130, maxWidth);
    // 竖线标出 maxWidth 的边界
    ctx.save();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = color("ink-3");
    ctx.beginPath();
    ctx.moveTo(40, 92);
    ctx.lineTo(40, 146);
    ctx.moveTo(40 + maxWidth, 92);
    ctx.lineTo(40 + maxWidth, 146);
    ctx.stroke();
    ctx.restore();
    note(ctx, color, "未限制宽度", 40, 80);
    note(ctx, color, `maxWidth = ${maxWidth}`, 40, 162);
  }, [maxWidth]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={180} />
      <Row>
        <Slider label="maxWidth" value={maxWidth} min={60} max={320} onChange={setMaxWidth} />
      </Row>
    </Demo>
  );
};
